import{_ as o,c as r,o as t,a5 as s}from"./chunks/framework.DYgWcJ6Z.js";const g=JSON.parse('{"title":"Using Chrome DevTools","description":"","frontmatter":{},"headers":[],"relativePath":"manual/developer-tools/using-chrome-devtools.md","filePath":"manual/developer-tools/using-chrome-devtools.md","lastUpdated":1755609385000}'),a={name:"manual/developer-tools/using-chrome-devtools.md"};function l(n,e,i,c,h,d){return t(),r("div",null,e[0]||(e[0]=[s(`<h1 id="using-chrome-devtools" tabindex="-1">Using Chrome DevTools <a class="header-anchor" href="#using-chrome-devtools" aria-label="Permalink to &quot;Using Chrome DevTools&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>This document describes how to use <a href="https://developer.chrome.com/docs/devtools/" target="_blank" rel="noreferrer">Chrome DevTools</a> to debug JSAR applications. Chrome DevTools is a set of developer tools built into the Chrome browser that provides powerful debugging, performance analysis, and development assistance features.</p><h2 id="what-is-chrome-devtools" tabindex="-1">What is Chrome DevTools <a class="header-anchor" href="#what-is-chrome-devtools" aria-label="Permalink to &quot;What is Chrome DevTools&quot;">​</a></h2><p><a href="https://developer.chrome.com/docs/devtools/" target="_blank" rel="noreferrer">Chrome DevTools</a> is a set of developer tools built into the Google Chrome browser. Its main features include:</p><ul><li><strong><a href="https://developer.chrome.com/docs/devtools/dom/" target="_blank" rel="noreferrer">Elements Panel</a></strong>: View and edit <a href="https://developer.mozilla.org/en-US/docs/Web/API/Document_Object_Model" target="_blank" rel="noreferrer">DOM</a> structure and <a href="https://developer.mozilla.org/en-US/docs/Web/CSS" target="_blank" rel="noreferrer">CSS</a> styles</li><li><strong><a href="https://developer.chrome.com/docs/devtools/console/" target="_blank" rel="noreferrer">Console Panel</a></strong>: Execute <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript" target="_blank" rel="noreferrer">JavaScript</a> code and view log output</li><li><strong><a href="https://developer.chrome.com/docs/devtools/javascript/" target="_blank" rel="noreferrer">Sources Panel</a></strong>: Debug <a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript" target="_blank" rel="noreferrer">JavaScript</a> code and set breakpoints</li><li><strong><a href="https://developer.chrome.com/docs/devtools/network/" target="_blank" rel="noreferrer">Network Panel</a></strong>: Monitor network requests and responses</li><li><strong><a href="https://developer.chrome.com/docs/devtools/performance/" target="_blank" rel="noreferrer">Performance Panel</a></strong>: Analyze application performance and rendering performance</li><li><strong><a href="https://developer.chrome.com/docs/devtools/memory/" target="_blank" rel="noreferrer">Memory Panel</a></strong>: Analyze memory usage</li><li><strong><a href="https://developer.chrome.com/docs/devtools/application/" target="_blank" rel="noreferrer">Application Panel</a></strong>: Manage storage, cache, and service workers</li></ul><p>Chrome DevTools provides an open protocol called <a href="https://chromedevtools.github.io/devtools-protocol/" target="_blank" rel="noreferrer">CDP (Chrome DevTools Protocol)</a> that enables any browser or application supporting CDP to be debugged using Chrome DevTools. This means developers can use the familiar Chrome DevTools interface to debug applications running in different environments, not just Chrome browser.</p><p><strong>JSAR CDP Support</strong>: JSAR currently supports a subset of the CDP protocol, allowing developers to use Chrome DevTools to debug JSAR applications with features like console logging, breakpoint debugging, and performance monitoring.</p><h2 id="start-using-chrome-devtools" tabindex="-1">Start using Chrome DevTools <a class="header-anchor" href="#start-using-chrome-devtools" aria-label="Permalink to &quot;Start using Chrome DevTools&quot;">​</a></h2><h3 id="official-release-builds" tabindex="-1">Official Release Builds <a class="header-anchor" href="#official-release-builds" aria-label="Permalink to &quot;Official Release Builds&quot;">​</a></h3><p>Official JSAR release builds have CDP (Chrome DevTools Protocol) enabled by default on port <strong>9423</strong>. You can directly connect to JSAR applications without any additional configuration.</p><h3 id="self-compiled-builds" tabindex="-1">Self-Compiled Builds <a class="header-anchor" href="#self-compiled-builds" aria-label="Permalink to &quot;Self-Compiled Builds&quot;">​</a></h3><p>If you&#39;re building JSAR from source, you need to enable the inspector during compilation:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Enable inspector support during build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> darwin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> INSPECTOR=yes</span></span></code></pre></div><h3 id="connecting-to-devtools" tabindex="-1">Connecting to DevTools <a class="header-anchor" href="#connecting-to-devtools" aria-label="Permalink to &quot;Connecting to DevTools&quot;">​</a></h3><ol><li><strong>Open Chrome Browser</strong></li><li><strong>Access Debug Page</strong>: Enter <a href="chrome://inspect" target="_blank" rel="noreferrer"><code>chrome://inspect</code></a> in the address bar</li><li><strong>Configure Network Target</strong>: Click &quot;Configure&quot; and add <code>localhost:9423</code></li><li><strong>Connect to Application</strong>: Find your JSAR application in the &quot;Remote Target&quot; list and click &quot;inspect&quot;</li></ol><p><img src="https://ar.rokidcdn.com/web-assets/pages/screenshot-chrome-devtools-inspect.png" alt="Chrome DevTools Inspect Screenshot" loading="lazy"></p><p><strong>For Remote Devices</strong></p><p>If your JSAR application is running on another device, you can replace <code>localhost</code> with the device&#39;s IP address. However, make sure to verify that the port is accessible:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check if the debug port is accessible</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:9423/json/list</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># For remote device, replace localhost with the device IP</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://192.168.1.100:9423/json/list</span></span></code></pre></div><p>Once connected, click &quot;inspect&quot; to start debugging your JSAR application with Chrome DevTools.</p><p><img src="http://ar.rokidcdn.com/web-assets/pages/screenshot-chrome-devtools-console.png" alt="Chrome DevTools Remote Debugging Screenshot" loading="lazy"></p>`,22)]))}const u=o(a,[["render",l]]);export{g as __pageData,u as default};
